class Solution:
    def minAreaRect(self, points):
        pts = set(map(tuple, points))
        best = float('inf')
        n = len(points)
        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]
                if x1 != x2 and y1 != y2:
                    if (x1, y2) in pts and (x2, y1) in pts:
                        best = min(best, abs(x2 - x1) * abs(y2 - y1))
        return best if best < float('inf') else 0

