    int minAreaRect(vector<vector<int>>& points) {
        map<int, vector<int>> cols;
        for (auto& p : points) cols[p[0]].push_back(p[1]);
        map<pair<int,int>, int> lastSeen;
        long long best = LLONG_MAX;
        for (auto& [x, ys] : cols) {
            sort(ys.begin(), ys.end());
            for (size_t i = 0; i < ys.size(); i++)
                for (size_t j = i + 1; j < ys.size(); j++) {
                    auto key = make_pair(ys[i], ys[j]);
                    auto it = lastSeen.find(key);
                    if (it != lastSeen.end())
                        best = min(best, (long long)(x - it->second) * (ys[j] - ys[i]));
                    lastSeen[key] = x;
                }
        }
        return best == LLONG_MAX ? 0 : (int)best;
    }
};

