import java.util.*;

class Solution {
    public int minAreaRect(int[][] points) {
        TreeMap<Integer, List<Integer>> cols = new TreeMap<>();
        for (int[] p : points)
            cols.computeIfAbsent(p[0], k -> new ArrayList<>()).add(p[1]);
        Map<Long, Integer> lastSeen = new HashMap<>();
        long best = Long.MAX_VALUE;
        for (Map.Entry<Integer, List<Integer>> e : cols.entrySet()) {
            int x = e.getKey();
            List<Integer> ys = e.getValue();
            Collections.sort(ys);
            for (int i = 0; i < ys.size(); i++)
                for (int j = i + 1; j < ys.size(); j++) {
                    long key = (long) ys.get(i) * 100001 + ys.get(j);
                    Integer prev = lastSeen.get(key);
                    if (prev != null)
                        best = Math.min(best, (long)(x - prev) * (ys.get(j) - ys.get(i)));
                    lastSeen.put(key, x);
                }
        }
        return best == Long.MAX_VALUE ? 0 : (int) best;
    }
}

